const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

const particles = 10000;
const positions = new Float32Array(particles * 3);
for (let i = 0; i < positions.length; i++) {
    positions[i] = (Math.random() - 0.5) * 10;
}

const geometry = new THREE.BufferGeometry();
geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

const material = new THREE.PointsMaterial({ color: 0xffcc00, size: 0.2, opacity: 0.8, transparent: true });
const pointCloud = new THREE.Points(geometry, material);
scene.add(pointCloud);

const light = new THREE.DirectionalLight(0xffffff, 1);
light.position.set(5, 5, 5).normalize();
scene.add(light);

const ambientLight = new THREE.AmbientLight(0x404040);
scene.add(ambientLight);

camera.position.z = 5;

const clock = new THREE.Clock();
function animate() {
    const delta = clock.getDelta();
    pointCloud.rotation.y += delta * 0.5;
    renderer.render(scene, camera);
    requestAnimationFrame(animate);
}

function explode() {
    const positions = geometry.attributes.position.array;
    for (let i = 0; i < positions.length; i += 3) {
        positions[i] += (Math.random() - 0.5) * 0.5;
        positions[i + 1] += (Math.random() - 0.5) * 0.5;
        positions[i + 2] += (Math.random() - 0.5) * 0.5;
    }
    geometry.attributes.position.needsUpdate = true;
}

setTimeout(explode, 1000);
setTimeout(() => { camera.position.z += 1; }, 1500);

const shakeCamera = () => {
    camera.position.x += (Math.random() - 0.5) * 0.1;
    camera.position.y += (Math.random() - 0.5) * 0.1;
};

function render() {
    shakeCamera();
    renderer.render(scene, camera);
    requestAnimationFrame(render);
}

animate();
render();

function checkout() {
    setTimeout(() => window.parent.postMessage("INSTALL_CLICK", "*"), 2500);
}
